parts.text:
{
  "references": [
    {
      "id": "R1",
      "summary_ko": "호스가 미끄러져 빠지기 전에 소방관이 먼저 넘어짐."
    },
    {
      "id": "R2",
      "summary_ko": "전반적으로 소방관이 물 호스를 대체로 통제하고 있는 것처럼 보임."
    },
    {
      "id": "R3",
      "summary_ko": "영상 전체에 걸쳐 호스의 모양과 너비가 여러 번 변함."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "특징 및 픽셀 구조 변화에 따른 형태/존재 변화 가능성 영역 제안(객체 미식별)."
    },
    {
      "id": "C2",
      "summary_ko": "작업자 형상, 물 분사 형태, 호스가 사람이 돌며 넘어질 때 부자연스럽게 왜곡되고 녹아내리며 변형됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 객체가 특정되지 않은 일반적인 측정 가설이므로 R1과 동일 현상인지 확정할 수 없습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 호스가 빠지기 전 소방관이 넘어지는 순서/인과적 문제인 반면, C2는 넘어지는 동안 인물과 호스가 녹고 변형되는 그래픽 왜곡 현상을 설명합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 특정 대상이 없는 측정 기반 제안으로, R2의 호스 제어 여부 설명과 일치하는지 판단하기 어렵습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R2는 호스 통제 여부에 대한 관찰인 반면, C2는 인물, 물줄기, 호스의 심각한 변형 및 왜곡 오류를 다룹니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1이 형태 변화 가능성을 언급하지만 대상 객체가 명시되지 않아 R3의 호스 형태 변화와 동일한지 불확실합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "두 설명 모두 호스의 형태 변화를 포함하고 있으나, C2는 소방관이 넘어지는 순간의 인물, 물, 호스 복합 변형을 집중적으로 기술하여 전반적인 호스 형명 변화(R3)와 완전히 일치하는지 불명확합니다."
    }
  ]
}
